import type { DecisionHistoryItem } from "@paperclipai/shared";
import { t } from "@/i18n";

// Interaction history labels are generated by decision-history.ts. Decision
// option labels may be authored by a person or an agent and remain unchanged.
export function coordinatorReceiptLabel(item: Pick<DecisionHistoryItem, "sourceKind" | "label">): string {
  if (item.sourceKind !== "issue_thread_interaction") return item.label;
  const keys: Record<string, string> = {
    Approved: "approved", "Changes requested": "changesRequested",
    "Answers recorded": "answersRecorded", Cancelled: "cancelled",
    Expired: "expired", Failed: "failed", Superseded: "superseded",
    "Answered in task": "answeredInTask", "Decision recorded": "decisionRecorded",
    "Review recorded": "reviewRecorded",
  };
  const key = keys[item.label];
  if (key) return t(`nov02Root.receipt.${key}`);
  // Match the complete server-generated grammar, never part of custom content.
  if (/^[1-9]\d* (?:approved|rejected|deferred)(?: · [1-9]\d* (?:approved|rejected|deferred))*$/.test(item.label)) {
    return item.label.split(" · ").map(part => {
      const [count, verdict] = part.split(" ");
      return t(`nov02Root.receiptCount.${verdict}`, { count: Number(count) });
    }).join(" · ");
  }
  return item.label;
}
